mkitem!{mkstruct!{# [doc = " Line and byte-column coordinates of a source code span within some file."] # [doc = " The file itself must be tracked separately."] # [derive (Clone , Copy , Debug)] pub (crate) struct Coords { # [doc = " 1-based starting line of the source code span."] pub (crate) start_line : u32 , # [doc = " 1-based starting column (in bytes) of the source code span."] pub (crate) start_col : u32 , # [doc = " 1-based ending line of the source code span."] pub (crate) end_line : u32 , # [doc = " 1-based ending column (in bytes) of the source code span. High bit must be unset."] pub (crate) end_col : u32 , }}}
mkitem!{mkimpl!{impl Coords { # [doc = " Attaches a local file ID to these coordinates to produce an `ffi::CoverageSpan`."] pub (crate) fn make_coverage_span (& self , local_file_id : LocalFileId) -> ffi :: CoverageSpan { let & Self { start_line , start_col , end_line , end_col } = self ; let file_id = local_file_id . as_u32 () ; ffi :: CoverageSpan { file_id , start_line , start_col , end_line , end_col } } }}}

