mkfn!{
    make_coords_introspect!();
    # [doc = " Converts the span into its start line and column, and end line and column."] # [doc = ""] # [doc = " Line numbers and column numbers are 1-based. Unlike most column numbers emitted by"] # [doc = " the compiler, these column numbers are denoted in **bytes**, because that's what"] # [doc = " LLVM's `llvm-cov` tool expects to see in coverage maps."] # [doc = ""] # [doc = " Returns `None` if the conversion failed for some reason. This should be uncommon,"] # [doc = " but it's hard to rule out entirely (especially in the presence of complex macros"] # [doc = " or other expansions), and if it does happen then skipping a span or function is"] # [doc = " better than an ICE or `llvm-cov` failure that the user might have no way to avoid."] pub (crate) fn make_coords (source_map : & SourceMap , file : & SourceFile , span : Span) -> Option < Coords > { if span . is_empty () { debug_assert ! (false , "can't make coords from empty span: {span:?}") ; return None ; } let lo = span . lo () ; let hi = span . hi () ; let line_and_byte_column = | pos : BytePos | -> Option < (usize , usize) > { let rpos = file . relative_position (pos) ; let line_index = file . lookup_line (rpos) ? ; let line_start = file . lines () [line_index] ; Some ((line_index + 1 , (rpos - line_start) . to_usize () + 1)) } ; let (mut start_line , start_col) = line_and_byte_column (lo) ? ; let (mut end_line , end_col) = line_and_byte_column (hi) ? ; start_line = source_map . doctest_offset_line (& file . name , start_line) ; end_line = source_map . doctest_offset_line (& file . name , end_line) ; check_coords (Coords { start_line : start_line as u32 , start_col : start_col as u32 , end_line : end_line as u32 , end_col : end_col as u32 , }) }
}

